"""The lock files of pip-compile, as Renovate reads them.

Renovate compiles a lock file such as requirements-dev.txt again with the command in
its header, as lib/modules/manager/pip-compile/common.ts and utils.ts of the version
that the Renovate workflow runs read it. It skips a file whose command it can't read,
in every run and with no more than the warning "pip-compile error" in its log: the
file gets no update from then on, not even one that fixes a vulnerability. A header of
`uv pip compile --python-version 3.12`, whose value without the = reads as one more
file to compile, kept a lock file of a project from Renovate that way. This module
says what keeps Renovate from compiling each lock file of the repository, and puts
the = between an option and its value, which is all that a command can fix there.

pip installs a lock file as it is, so a change of its source, such as requirements.in,
reaches no install until the file is compiled again. This module also compiles each
lock file again with the command in its header, for the Python and the system that
the file holds for, and compares the pins; the fix keeps the result below the header
of the file. uv does it for both kinds of header: it depends on no Python that runs
it, it takes seconds, and it prefers what the file pins, so that a new release upstream
never makes a file differ."""

from __future__ import annotations

import re
import shlex
import subprocess
import sys
import tempfile
from collections.abc import Iterable
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta
from itertools import takewhile
from pathlib import Path, PurePosixPath

from blueprint.diagrams import git

# The files that Renovate's pip-compile finds, by the managerFilePatterns of
# .github/renovate-blueprint.json5, other than in the ignorePaths there.
PATTERN = re.compile(r"(^|/)requirements[^/]*\.txt$")
IGNORED = {"node_modules", "vendor"}
# The ignorePaths that the project adds in .github/renovate.json5, for a file such as
# a requirements.txt for Read the Docs that is no lock file.
PROJECT_RULES = ".github/renovate.json5"
IGNORE_PATHS = re.compile(
    r"""(?:^|[\s{,])["']?ignorePaths["']?\s*:\s*\[(.*?)\]""", re.S
)
QUOTED = re.compile(r"""["']([^"']*)["']""")
COMMENT = re.compile(r"^\s*//[^\n]*|/\*.*?\*/", re.M | re.S)
WILDCARDS = {"**/": "(?:.*/)?", "**": ".*", "*": "[^/]*", "?": "[^/]"}
HEADER = re.compile(r"^(?:#.*?\r?\n)+# {4}(?P<command>\S*)(?P<arguments> .*?)?\r?\n")
PYTHON_OF_PIP_COMPILE = re.compile(
    r"^(?:#.*?\r?\n)*# This file is autogenerated by pip-compile with Python "
    r"(?P<python>\d+(?:\.\d+)*)\s",
    re.IGNORECASE,
)
# The options that Renovate allows, those with a value only with an = before it.
WITH_A_VALUE = {"--output-file", "--extra", "--extra-index-url"}
PIP_WITH_A_VALUE = {"--resolver", "--constraint", *WITH_A_VALUE}
UV_WITH_A_VALUE = {
    *("--constraints", "--constraint", "--python-version", "--no-emit-package"),
    *("--prerelease", "--format", "--resolution", "--fork-strategy"),
    *("--exclude-newer", "--exclude-newer-package", "--group", "--override"),
    *("--overrides", *WITH_A_VALUE),
}
FOR_BOTH = {
    "-v",
    "--generate-hashes",
    "--emit-index-url",
    "--index-url",
    "--all-extras",
}
KNOWN_OPTIONS = {
    "pip-compile": {
        *("--allow-unsafe", "--generate-hashes", "--no-emit-index-url"),
        *("--strip-extras", *FOR_BOTH, *PIP_WITH_A_VALUE),
    },
    "uv": {"--no-strip-extras", "--universal", *FOR_BOTH, *UV_WITH_A_VALUE},
}
OPTIONS_WITH_A_VALUE = PIP_WITH_A_VALUE | UV_WITH_A_VALUE
# What a compile by uv leaves out of a command: the output, which is a copy of the file,
# and -v, which --quiet refuses; of pip-compile also what uv does by itself or knows not.
NOT_FOR_UV = {"pip", "compile", "-v", "--output-file"}
NOT_FOR_PIP = {
    *("-v", "--output-file"),
    *("--allow-unsafe", "--strip-extras", "--no-emit-index-url", "--resolver"),
}
# The header of pip-compile names a Python without its patch release, and Renovate takes
# the newest one, which a package may ask for: Home Assistant 2026.10.4 needs Python
# 3.14.2 or newer. uv takes a version without one for the release .0 of that Python.
PATCH = ".99"
# What pip-compile leaves out of a lock file without --allow-unsafe.
UNSAFE = ("distribute", "pip", "setuptools")
# The system of Renovate and the CI, for which a lock file holds unless it is universal:
# Ubuntu 24.04 with its glibc. For uv, "linux" means manylinux_2_28, where a pin whose
# only wheels ask for a newer glibc has no wheel, and uv would pick an older version.
SYSTEM = "x86_64-manylinux_2_39"
# A line of a lock file that pins a package: name[extras]==version, or name @ address.
PIN = re.compile(
    r"(?P<name>[A-Za-z0-9][\w.-]*)(?:\[[^\]]*\])?\s*"
    r"(?:==\s*(?P<version>[^\s;\\]+)|@\s)"
)
# What uv says when it reaches no package index, which says nothing of the file.
NOT_REACHED = re.compile("Request failed|Failed to fetch|Failed to download")
UNREADABLE = "a command that Renovate can't read, which the step Lock files explains"
NO_PIN = "a line that is no pin of a package"
NO_PYTHON = "no --python-version= in its command, and so no Python to compile it for"


@dataclass(frozen=True)
class Skipped:
    """A lock file that Renovate can't compile again, and why."""

    name: str
    problems: list[str]

    def __str__(self) -> str:
        return f"{self.name}: Renovate skips it, for {'; '.join(self.problems)}."


def ignored_by_the_project(root: Path) -> list[str]:
    """The ignorePaths that the project sets in .github/renovate.json5; none when it
    has no such file or sets none."""
    rules = root / PROJECT_RULES
    if not rules.is_file():
        return []
    paths = IGNORE_PATHS.search(COMMENT.sub("", rules.read_text(encoding="utf-8")))
    return QUOTED.findall(paths[1]) if paths else []


def is_ignored(name: str, ignore_paths: list[str]) -> bool:
    """Whether Renovate leaves the file out for one of the ignorePaths, as it matches
    them: a part of the path, or a glob of minimatch that matches all of it."""
    for path in filter(None, ignore_paths):
        parts = re.split(r"(\*\*/|\*\*|\*|\?)", path)
        glob = "".join(WILDCARDS.get(part, re.escape(part)) for part in parts)
        if path in name or re.fullmatch(glob, name):
            return True
    return False


def lock_files(root: Path) -> list[str]:
    """Every lock file of pip-compile of the repository, as Renovate finds them:
    without what git or the ignorePaths of the blueprint and the project leave out."""
    listed = git(root, "ls-files", "-z", "--cached", "--others", "--exclude-standard")
    ignore_paths = ignored_by_the_project(root)
    return sorted(
        name
        for name in set(listed.split("\0"))
        if PATTERN.search(name)
        and not IGNORED & set(PurePosixPath(name).parts)
        and not is_ignored(name, ignore_paths)
        and (root / name).is_file()
    )


def why_renovate_skips(root: Path, name: str) -> list[str]:
    """What keeps Renovate from compiling the lock file root/name again; nothing for a
    file that it reads."""
    content = (root / name).read_text(encoding="utf-8")
    header = HEADER.match(content)
    if not header:
        return ["no command in the header"]
    command = header["command"]
    if command not in KNOWN_OPTIONS:
        return [f"{command}, a command of its own"]
    problems = []
    sources, output = [], ""
    for argument in shlex.split(header["arguments"] or ""):
        if command == "uv" and argument in ("pip", "compile"):
            continue
        if not argument.startswith("-"):
            sources.append(argument)
            continue
        option, _, value = argument.partition("=")
        if argument == "--no-header":
            problems.append("--no-header, which Renovate refuses")
        elif argument in OPTIONS_WITH_A_VALUE:
            problems.append(f"{argument} without = before its value")
        elif option not in KNOWN_OPTIONS[command]:
            problems.append(f"{argument}, an option that Renovate doesn't know")
        elif option == "--output-file":
            output = value
    # Renovate finds the folder of the command from the path of the output file.
    if output and Path(output).name != Path(name).name:
        problems.append(f"{output} as the output file")
    if not sources:
        problems.append("no source file")
    for source in sources:
        if not (root / name).parent.joinpath(source).is_file():
            problems.append(f"{source}, a source file that doesn't exist")
    # The Python to compile it for, which Renovate installs.
    if command == "pip-compile" and not PYTHON_OF_PIP_COMPILE.match(content):
        problems.append("no Python in the header")
    return problems


def with_equal_signs(content: str) -> str:
    """The content of a lock file with an = between each option of its command and
    the value that follows it as an argument of its own, as Renovate needs it; the
    content as it is when it has no such option."""
    header = HEADER.match(content)
    if not header or header["command"] not in KNOWN_OPTIONS or not header["arguments"]:
        return content
    options = "|".join(map(re.escape, sorted(OPTIONS_WITH_A_VALUE)))
    arguments = re.sub(rf"(?<= )({options}) +(?=[^\s-])", r"\1=", header["arguments"])
    start, end = header.span("arguments")
    return content[:start] + arguments + content[end:]


def check(root: Path) -> tuple[list[str], list[Skipped]]:
    """The lock files of the repository, and those among them that Renovate skips."""
    names = lock_files(root)
    skipped = []
    for name in names:
        if problems := why_renovate_skips(root, name):
            skipped.append(Skipped(name, problems))
    return names, skipped


def fix(root: Path, skipped: list[Skipped]) -> list[str]:
    """Put the = between each option and its value in the lock files that Renovate
    skips: the names of the files that changed."""
    fixed = []
    for lock in skipped:
        path = root / lock.name
        # As bytes, so that the file keeps its line endings.
        content = path.read_bytes().decode("utf-8")
        if (changed := with_equal_signs(content)) != content:
            path.write_bytes(changed.encode("utf-8"))
            fixed.append(lock.name)
    return fixed


# ---------------------------------------------------------------- compiled again


@dataclass(frozen=True)
class Pins:
    """What a lock file pins, each as name==version or, by an address, as name @, and
    those among them without a hash."""

    pinned: frozenset[str]
    without_hash: frozenset[str]


@dataclass(frozen=True)
class Compared:
    """What a compile of a lock file found: how its pins differ from those of the file,
    with the file as the compile wants it; what uv said when it found no pins; or why
    the check didn't compare it."""

    name: str
    differences: tuple[str, ...] = ()
    content: bytes = b""
    failure: str = ""
    note: str = ""


def read_pins(content: str) -> Pins | None:
    """The pins of a lock file, without the spelling of a name, its extras, its markers
    and the commit of an address, none of which uv and pip-compile write alike, and
    without the hashes themselves, which a new wheel of a pinned version adds to; none
    for a file with a line that is neither of these nor a comment, such as an index,
    which uv writes only with an option of its own."""
    pinned: set[str] = set()
    hashed: set[str] = set()
    pin = ""
    for line in content.splitlines():
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        if line[0].isspace():
            if not pin or not text.startswith("--hash="):
                return None
            hashed.add(pin)
            continue
        found = PIN.match(line)
        if not found:
            return None
        name = re.sub(r"[-_.]+", "-", found["name"]).lower()
        pin = f"{name}=={found['version']}" if found["version"] else f"{name} @"
        pinned.add(pin)
    return Pins(frozenset(pinned), frozenset(pinned - hashed))


def compile_options(header: re.Match[str], content: str) -> list[str] | None:
    """The options and the sources of the command of a lock file that Renovate reads,
    as uv takes them, for the Python and the system that the file holds for: a compile
    must not depend on the machine that runs it (repo-blueprint#127). None when the
    file names no Python."""
    uses_uv = header["command"] == "uv"
    arguments = shlex.split(header["arguments"] or "")
    options = [
        argument
        for argument in arguments
        if argument.partition("=")[0] not in (NOT_FOR_UV if uses_uv else NOT_FOR_PIP)
    ]
    python = PYTHON_OF_PIP_COMPILE.match(content)
    if python and not uses_uv:
        options.append(f"--python-version={python['python']}{PATCH}")
        if "--allow-unsafe" not in arguments:
            options += [f"--no-emit-package={package}" for package in UNSAFE]
        if "--strip-extras" not in arguments:
            options.append("--no-strip-extras")
    if not any(option.startswith("--python-version=") for option in options):
        return None
    if "--universal" not in options:
        options.append(f"--python-platform={SYSTEM}")
    return options


def header_of(content: str) -> str:
    """The comments at the top of a lock file."""
    lines = content.splitlines(keepends=True)
    return "".join(takewhile(lambda line: line.startswith("#"), lines))


def compile_onto(
    path: Path, content: str, options: list[str], uv: str, constraints: str = ""
) -> tuple[subprocess.CompletedProcess[str], str]:
    """uv's answer to a compile of the lock file at path with these options, and the
    lock file that it wrote, without a header: onto a copy that holds content, whose
    pins uv prefers and whose hashes it keeps, and with constraints, the lines of a
    file of constraints, when there are any. The command is arguments for uv, never a
    line for a shell, and the file at path stays as it is."""
    with tempfile.TemporaryDirectory(prefix="locks-") as folder:
        copy = Path(folder, path.name)
        copy.write_bytes(content.encode("utf-8"))
        bounds = []
        if constraints:
            file = Path(folder, "constraints.txt")
            file.write_text(constraints, encoding="utf-8")
            bounds.append(f"--constraint={file}")
        result = subprocess.run(
            [
                *(uv, "pip", "compile", *options, *bounds, "--no-header", "--quiet"),
                f"--python={sys.executable}",
                f"--output-file={copy}",
            ],
            cwd=path.parent,
            capture_output=True,
            encoding="utf-8",
            errors="replace",
            check=False,
        )
        body = copy.read_bytes().decode("utf-8")
    return result, without_source(body, Path(folder).name) if constraints else body


def without_source(body: str, folder: str) -> str:
    """The lock file body without the file of constraints in the temporary folder of
    that name among the sources that uv names after `# via`: the folder differs in
    every run and means nothing in the repository. A note that keeps one source of
    several takes uv's form of one line again, `# via -r requirements.in`."""
    source = re.compile(rf"-c \S*{re.escape(folder)}[/\\]constraints\.txt")
    lines = body.splitlines(keepends=True)
    kept: list[str] = []
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        via = re.fullmatch(r"(\s*)# via\n", line)
        if via:
            # uv's note of several sources, one below the other.
            items = []
            while index < len(lines) and lines[index].startswith(f"{via[1]}#   "):
                items.append(lines[index])
                index += 1
            left = [item for item in items if not source.search(item)]
            if len(left) == len(items):
                kept += [line, *items]
            elif len(left) == 1:
                kept.append(f"{via[1]}# via {left[0].strip().removeprefix('#   ')}\n")
            elif left:
                kept += [line, *left]
            continue
        note = re.search(r"(\s*)# via (.*)$", line)
        if note and source.search(note[2]):
            # uv's note in one line, also with --annotation-style=line.
            sources = [
                part for part in note[2].split(", ") if not source.fullmatch(part)
            ]
            end = "\n" if line.endswith("\n") else ""
            line = line[: note.start()] + (
                f"{note[1]}# via {', '.join(sources)}{end}" if sources else end
            )
            if not line.strip():
                continue
        kept.append(line)
    return "".join(kept)


def compare(root: Path, name: str, uv: str) -> Compared:
    """Compiles the lock file root/name again with the command in its header and says
    what differs. uv compiles onto a copy of the file, whose pins it prefers and whose
    hashes it keeps: only a change of the sources moves a pin, not a new release. The
    command is arguments for uv, never a line for a shell, and the file stays as it is
    until the fix writes it."""
    path = root / name
    if path.is_symlink():
        return Compared(name, note="a link, which the check doesn't write through")
    content = path.read_bytes().decode("utf-8")
    header = HEADER.match(content)
    if not header or why_renovate_skips(root, name):
        return Compared(name, note=UNREADABLE)
    pins = read_pins(content)
    if pins is None:
        return Compared(name, note=f"{NO_PIN}, such as an index")
    options = compile_options(header, content)
    if options is None:
        return Compared(name, note=NO_PYTHON)
    result, body = compile_onto(path, content, options, uv)
    if result.returncode:
        if NOT_REACHED.search(result.stderr):
            return Compared(name, note="a package index that uv didn't reach")
        return Compared(name, failure=result.stderr.rstrip())
    found = read_pins(body)
    if found is None:
        return Compared(name, note=f"an answer of uv with {NO_PIN}")
    lost_hashes = (pins.without_hash & found.pinned) - found.without_hash
    differences = (
        *(f"they ask for {pin}" for pin in sorted(found.pinned - pins.pinned)),
        *(
            f"they no longer ask for {pin}"
            for pin in sorted(pins.pinned - found.pinned)
        ),
        *(f"{pin} has no hash" for pin in sorted(lost_hashes)),
    )
    return Compared(name, differences, (header_of(content) + body).encode("utf-8"))


# ---------------------------------------------------------------- the weekly refresh

# The refresh keeps to versions as old as every other update of Renovate waits for,
# the minimumReleaseAge of .github/renovate-blueprint.json5 (decision 0137).
AGE = timedelta(days=7)
# What uv says of a file that it can't take a week back alone.
OWN_CUTOFF = "an --exclude-newer of its own, which the refresh keeps"


def cutoff(now: datetime) -> datetime:
    """The newest upload that the refresh takes: a week before the start of the day of
    now, in UTC, so that every run of Renovate on one day compiles alike and none
    builds a new refresh right after one merged."""
    day = now.astimezone(UTC).replace(hour=0, minute=0, second=0, microsecond=0)
    return day - AGE


def stamp(moment: datetime) -> str:
    """A moment as uv takes it, in UTC."""
    return moment.astimezone(UTC).strftime("%Y-%m-%dT%H:%M:%SZ")


def refreshed(root: Path) -> list[str]:
    """The lock files of pip-compile that differ from HEAD: in Renovate's checkout of
    a branch of the refresh, those that it compiled anew."""
    changed = set(git(root, "diff", "--name-only", "-z", "HEAD", "--").split("\0"))
    return [name for name in lock_files(root) if name in changed]


def by_name(pins: Iterable[str]) -> dict[str, set[str]]:
    """The versions that the pins name for each package; none for a pin by address."""
    versions: dict[str, set[str]] = {}
    for pin in pins:
        name, separator, version = pin.partition("==")
        if separator:
            versions.setdefault(name, set()).add(version)
    return versions


def pins_of_head(root: Path, name: str) -> dict[str, set[str]]:
    """What the lock file root/name pins in HEAD; nothing for a file that HEAD
    doesn't have, or one with a line that is no pin."""
    try:
        content = git(root, "show", f"HEAD:{name}")
    except subprocess.CalledProcessError:
        return {}
    pins = read_pins(content)
    return by_name(pins.pinned) if pins else {}


def refresh(root: Path, name: str, uv: str, now: datetime) -> Compared:
    """Compiles the lock file root/name again, which Renovate's refresh moved to the
    newest version of every package, from uploads at least a week before the day of
    now. A package that the refresh pins as HEAD does keeps its pin, also a young one
    such as the fix of a vulnerability that came at once; a package that it moved
    stays at least at the version of HEAD, so that no fix goes back, and uv says so
    when no version both that new and a week old exists. The differences are the
    pins of the refresh that the week took back."""
    path = root / name
    if path.is_symlink():
        return Compared(name, note="a link, which the refresh doesn't write through")
    content = path.read_bytes().decode("utf-8")
    header = HEADER.match(content)
    if not header or why_renovate_skips(root, name):
        return Compared(name, note=UNREADABLE)
    pins = read_pins(content)
    if pins is None:
        return Compared(name, note=f"{NO_PIN}, such as an index")
    options = compile_options(header, content)
    if options is None:
        return Compared(name, note=NO_PYTHON)
    if any(option.startswith("--exclude-newer") for option in options):
        return Compared(name, note=OWN_CUTOFF)
    head = pins_of_head(root, name)
    kept = sorted(
        package
        for package, versions in by_name(pins.pinned).items()
        if versions & head.get(package, set())
    )
    floors = "".join(
        f"{package}>={next(iter(versions))}\n"
        for package, versions in sorted(head.items())
        if package not in kept and len(versions) == 1
    )
    options += [
        f"--exclude-newer={stamp(cutoff(now))}",
        *(f"--exclude-newer-package={package}={stamp(now)}" for package in kept),
    ]
    result, body = compile_onto(path, content, options, uv, floors)
    if result.returncode:
        return Compared(name, failure=result.stderr.rstrip())
    found = read_pins(body)
    if found is None:
        return Compared(name, failure=f"uv answered with {NO_PIN}:\n{body.rstrip()}")
    return Compared(
        name,
        tuple(sorted(pins.pinned - found.pinned)),
        (header_of(content) + body).encode("utf-8"),
    )


def write_refresh(root: Path, found: Compared) -> None:
    """Writes the lock file that the refresh compiled again into Renovate's checkout.
    Renovate reads after its command only the files that git names as changed, and
    keeps its own compile of every other one: when the week takes each pin back to
    that of HEAD, the file equals HEAD, and git would name it no more. Renovate's
    compile goes into the index first, so that git names the file in either case and
    Renovate takes what the command wrote."""
    git(root, "add", "--", found.name)
    (root / found.name).write_bytes(found.content)
